<?php if(canManageCatalog($user)):?><section class="card"><h2><?=$editing?'Sửa điểm bán':'Thêm điểm bán'?></h2><form method="post" class="form"><?=csrfInput()?><input type="hidden" name="id" value="<?=e((string)($editing['id']??''))?>"><div class="form-row"><label class="form-field">Mã<input name="code" required maxlength="40" value="<?=e($editing['code']??'')?>"></label><label class="form-field form-field--wide">Tên<input name="name" required maxlength="200" value="<?=e($editing['name']??'')?>"></label><label class="form-field">Loại<select name="point_type" required><?php foreach(['AGENT'=>'Đại lý','STORE'=>'Cửa hàng','SUPERMARKET'=>'Siêu thị'] as $k=>$v):?><option value="<?=$k?>" <?=($editing['point_type']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="form-field">Kho phụ trách<select name="primary_warehouse_id" required><?php foreach($warehouses as $w): if(!$w['active'])continue;?><option value="<?=$w['id']?>" <?=($editing['primary_warehouse_id']??0)===$w['id']?'selected':''?>><?=e($w['code'].' · '.$w['name'])?></option><?php endforeach;?></select></label><label class="form-field form-field--wide">Địa chỉ<input name="address" value="<?=e($editing['address']??'')?>"></label><label class="form-field">Người liên hệ<input name="contact_name" value="<?=e($editing['contact_name']??'')?>"></label><label class="form-field">Điện thoại<input name="phone" value="<?=e($editing['phone']??'')?>"></label><label><input type="checkbox" name="active" <?=!isset($editing['active'])||$editing['active']?'checked':''?>> Đang hoạt động</label></div><button class="button">Lưu</button></form></section><?php endif;?>
<section class="card table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Điểm bán</th><th>Loại</th><th>Kho phụ trách</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($points as $p):?><tr><td><?=e($p['code'])?></td><td><strong><?=e($p['name'])?></strong><br><span class="muted"><?=e($p['address'])?></span></td><td><?=e($p['point_type'])?></td><td><?=e(warehouseName($p['primary_warehouse_id']))?></td><td><?=$p['active']?'Đang hoạt động':'Ngừng hoạt động'?></td><td><?php if(canManageCatalog($user)):?><a class="text-link" href="/sales-points.php?edit=<?=$p['id']?>">Sửa</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
